public final class BatchToken {
    private BatchToken() {}
    public static int quantity(String token) {
        if (token == null) throw new IllegalArgumentException("Missing token");
        String[] fields = token.split("@", -1);
        if (fields.length != 2 || fields[0].isEmpty() || fields[0].length() > 8
                || fields[1].isEmpty() || fields[1].length() > 3) throw new IllegalArgumentException("Invalid token");
        for (char c : fields[0].toCharArray()) if (c < 'A' || c > 'Z') throw new IllegalArgumentException("Invalid tag");
        for (char c : fields[1].toCharArray()) if (c < '0' || c > '9') throw new IllegalArgumentException("Invalid quantity");
        return Integer.parseInt(fields[1]);
    }
}
